	}
	input.Normalize()

	if input.ConversationID != "conv-42" {
		t.Errorf("got %q, want conv-42", input.ConversationID)
	}
	if input.TranscriptPath != "/tmp/transcript.jsonl" {
		t.Errorf("got %q, want /tmp/transcript.jsonl", input.TranscriptPath)
